#!/usr/bin/env bash
# Fake gh CLI for evals: logs every call, serves canned issue data, and
# records what `issue create` would file in .fixture/created-*.
printf 'gh' >> .gh-calls.log; printf ' %q' "$@" >> .gh-calls.log; echo >> .gh-calls.log
case "$1 $2" in
  "auth status")
    [ -f .fixture/unauthenticated ] && { echo "You are not logged into any GitHub hosts. Run gh auth login" >&2; exit 1; }
    echo "Logged in to github.com (fake)"; exit 0 ;;
  "repo view") echo '{"nameWithOwner":"acme/csvkit-demo"}'; exit 0 ;;
  "label list") printf 'bug\tSomething is broken\t#d73a4a\nenhancement\tNew feature\t#a2eeef\narea:export\tCSV export\t#ededed\n'; exit 0 ;;
  "issue list") cat .fixture/issue-list.txt; exit 0 ;;
  "issue view") cat ".fixture/issue-${3#\#}.txt" 2>/dev/null || { echo "issue not found" >&2; exit 1; }; exit 0 ;;
  "search issues") cat .fixture/search.txt; exit 0 ;;
  "issue create")
    shift 2
    while [ $# -gt 0 ]; do
      case "$1" in
        --title|-t) printf '%s\n' "$2" > .fixture/created-title.txt; shift ;;
        --title=*) printf '%s\n' "${1#--title=}" > .fixture/created-title.txt ;;
        --label|-l) printf '%s\n' "$2" >> .fixture/created-labels.txt; shift ;;
        --label=*) printf '%s\n' "${1#--label=}" >> .fixture/created-labels.txt ;;
        --body-file|-F) cat "$2" > .fixture/created-body.md; shift ;;
        --body|-b) printf '%s\n' "$2" > .fixture/created-body.md; shift ;;
      esac
      shift
    done
    echo "https://github.com/acme/csvkit-demo/issues/12"; exit 0 ;;
  *) echo "{}"; exit 0 ;;
esac

